INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('operation.onchainpulse.get-api-iso-receipt-3da9943a','Bank-reconcilable receipt for any on-chain settlement: turn a transaction hash into an ISO 20022 camt.054-style credit notification (XML + JSON), a deterministic evidence bundle wi','Bank-reconcilable receipt for any on-chain settlement: turn a transaction hash into an ISO 20022 camt.054-style credit notification (XML + JSON), a deterministic evidence bundle with canonical SHA-256 hashes, and an Ed25519 signature anyone can verify without an API key at /verify.html. Same tx always yields a byte-identical bundle. Covers ERC-20 transfers (incl. x402 USDC settlements) on 11 EVM chains. Params: tx (hash, required), chain (default base), perspective (address).','source_document','{}','{}','active') ON CONFLICT(slug) DO NOTHING;
