INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('operation.cryptopulse.get-api-volatility-check-5bbe3341','Volatility check for a perp market, deterministic. Answers "how volatile is this coin right now", "is the range compressing or expanding". Computed in code from Hyperliquid candles','Volatility check for a perp market, deterministic. Answers "how volatile is this coin right now", "is the range compressing or expanding". Computed in code from Hyperliquid candles: annualized realized volatility (log-return stdev), NATR (Wilder ATR-14 / price), Bollinger(20,2) width percent and percent-B, window high/low and distance from each, over a chosen interval (15m|1h|4h|1d) and lookback. No LLM, no key, keyless public data.','source_document','{}','{}','active') ON CONFLICT(slug) DO NOTHING;
