INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('operation.compliancepulse.get-api-screen-sanctions-96e543e5','Is this person or company sanctioned? Screens a name against the live US Treasury OFAC SDN and Consolidated (non-SDN) lists — sanctions screening, watchlist check, KYC/AML pre-chec','Is this person or company sanctioned? Screens a name against the live US Treasury OFAC SDN and Consolidated (non-SDN) lists — sanctions screening, watchlist check, KYC/AML pre-check, counterparty screening before a payment. Fuzzy-matches primary names AND every OFAC alias, so transliteration and word-order variants still hit. Deterministic: no LLM. Returns official OFAC rows verbatim (programs, SDN uid, remarks) with a 0-100 match score.','source_document','{}','{}','active') ON CONFLICT(slug) DO NOTHING;
