INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('operation.companies-house.get-disqualified-officers-corporate-9b160607','The full disqualification record of one banned CORPORATE officer — a company or other body corporate that has itself been disqualified from acting as a director — by officer id fro','The full disqualification record of one banned CORPORATE officer — a company or other body corporate that has itself been disqualified from acting as a director — by officer id from the disqualified-officer search. Returns the same structure as the natural-person record: the dates the disqualification runs from and to, whether it was a court order or an undertaking, the Act and section relied on, the case identifier, the reasons, the companies the conduct related to, and any permissions to act. Corporate disqualifications are rarer than individual ones and are held in a separate index, which is why this is a different call from /disqualified-officers/natural — use the kind on the search hit to pick between them.','source_document','{}','{}','active') ON CONFLICT(slug) DO NOTHING;
