INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('operation.insurepulse.get-api-insure-prompt-pay-fe97931f','Late-claim interest check — insurers owe STATUTORY INTEREST when they pay late, and most policyholders never collect it. Deterministic day-count math: TX 18%/yr + fees (weather cla','Late-claim interest check — insurers owe STATUTORY INTEREST when they pay late, and most policyholders never collect it. Deterministic day-count math: TX 18%/yr + fees (weather claims prime+5 w/ 542A notice), FL property from the NOTICE date (CFO quarterly table), NY no-fault 2%/month, AZ 10%, GA health 12%, CA health 15% + auto-include penalty. ERISA self-funded gate, clean-claim assumptions stated, limitations gates. Honest-no where the interest belongs to the provider. No LLM.','source_document','{}','{}','active') ON CONFLICT(slug) DO NOTHING;
